// Generated from the canonical mappings in UnicodeData 14.0 and recursively
// flattened to NFD. Hangul syllables use the algorithm from Unicode Standard
// Annex #15. Unicode normalization stability guarantees these mappings do not
// change in later Unicode versions.
internal fun decomposeUnicodeForIndex(value: String): String {
    val decomposed = StringBuilder(value.length)
    var index = 0
    while (index < value.length) {
        val first = value[index]
        val isSurrogatePair = first.isHighSurrogate() &&
            index + 1 < value.length &&
            value[index + 1].isLowSurrogate()
        val codePoint = if (isSurrogatePair) {
            index++
            0x10000 + ((first.code - 0xd800) shl 10) + (value[index].code - 0xdc00)
        } else {
            first.code
        }

        appendCanonicalDecomposition(codePoint, decomposed)
        index++
    }
    return decomposed.toString()
}

private fun appendCanonicalDecomposition(codePoint: Int, target: StringBuilder) {
    if (codePoint in HANGUL_SYLLABLE_BASE until HANGUL_SYLLABLE_BASE + HANGUL_SYLLABLE_COUNT) {
        val syllableIndex = codePoint - HANGUL_SYLLABLE_BASE
        appendCodePoint(HANGUL_LEADING_BASE + syllableIndex / HANGUL_LEADING_COUNT, target)
        appendCodePoint(HANGUL_VOWEL_BASE + (syllableIndex % HANGUL_LEADING_COUNT) / HANGUL_TRAILING_COUNT, target)
        val trailingIndex = syllableIndex % HANGUL_TRAILING_COUNT
        if (trailingIndex != 0) {
            appendCodePoint(HANGUL_TRAILING_BASE + trailingIndex, target)
        }
        return
    }

    val decompositionIndex = canonicalDecompositionIndex(codePoint)
    if (decompositionIndex < 0) {
        appendCodePoint(codePoint, target)
        return
    }

    val start = canonicalDecompositionOffsets[decompositionIndex].code
    val end = canonicalDecompositionOffsets[decompositionIndex + 1].code
    target.append(canonicalDecompositionValues, start, end)
}

private fun canonicalDecompositionIndex(codePoint: Int): Int {
    var low = 0
    var high = canonicalDecompositionOffsets.length - 2
    while (low <= high) {
        val middle = (low + high).ushr(1)
        val sourceOffset = middle * 2
        val source = (canonicalDecompositionSources[sourceOffset].code shl 16) or
            canonicalDecompositionSources[sourceOffset + 1].code
        when {
            source < codePoint -> low = middle + 1
            source > codePoint -> high = middle - 1
            else -> return middle
        }
    }
    return -1
}

private fun appendCodePoint(codePoint: Int, target: StringBuilder) {
    if (codePoint <= 0xffff) {
        target.append(codePoint.toChar())
    } else {
        val supplementary = codePoint - 0x10000
        target.append((0xd800 + (supplementary shr 10)).toChar())
        target.append((0xdc00 + (supplementary and 0x3ff)).toChar())
    }
}

